// ScrolledWindow — Gtk.ScrolledWindow
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles scrolledwindow with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { CornerType, PolicyType } from "@/lib/enums"

export interface ScrolledWindowProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.ScrolledWindow */
  child?: ReactNode

  /** Adjustment, from Gtk.ScrolledWindow */
  hadjustment?: ReactNode

  /** gboolean, from Gtk.ScrolledWindow */
  hasFrame?: boolean

  /** PolicyType, from Gtk.ScrolledWindow */
  hscrollbarPolicy?: PolicyType

  /** gboolean, from Gtk.ScrolledWindow */
  kineticScrolling?: boolean

  /** gint, from Gtk.ScrolledWindow */
  maxContentHeight?: number

  /** gint, from Gtk.ScrolledWindow */
  maxContentWidth?: number

  /** gint, from Gtk.ScrolledWindow */
  minContentHeight?: number

  /** gint, from Gtk.ScrolledWindow */
  minContentWidth?: number

  /** gboolean, from Gtk.ScrolledWindow */
  overlayScrolling?: boolean

  /** gboolean, from Gtk.ScrolledWindow */
  propagateNaturalHeight?: boolean

  /** gboolean, from Gtk.ScrolledWindow */
  propagateNaturalWidth?: boolean

  /** Adjustment, from Gtk.ScrolledWindow */
  vadjustment?: ReactNode

  /** PolicyType, from Gtk.ScrolledWindow */
  vscrollbarPolicy?: PolicyType

  /** CornerType, from Gtk.ScrolledWindow */
  windowPlacement?: CornerType
}

export function ScrolledWindow({ className, children }: ScrolledWindowProps) {
  return (
    <div className={cn("[filter:none]", className)}>
      {children}
    </div>
  )
}
